using UnityEngine;

namespace Astrea.GameStates;

[CreateAssetMenu(fileName = "RandomTargetCastStateMouseAction", menuName = "Data/Battle/Actions/RandomTargetCastStateMouseAction")]
public class RandomTargetCastStateMouseAction : NoTargetCastStateMouseAction
{
	[SerializeField]
	private bool randomTargetXTimes;

	protected override void CastAction()
	{
		if (randomTargetXTimes)
		{
			NoTargetCastAction();
		}
		else
		{
			RandomTargetCastAction();
		}
	}
}
